@startuml

class SensorController {
  + systemName : string
  + querySensorValues(inhabitantId : string) : float[]
}

class Inhabitant {
  + username : string
  + password : string
  + email : string
}

class Apartment {
  + address : string
}

class Room {
  + description : string
}

abstract class Sensor {
  + vendorId : string
  + description : string
  + unit : Unit
  + threshold : float
}

class TemperatureSensor {
  + minValue : float
  + maxValue : float
}

class PowerSensor {
  + totalConsumption : float
}

class MeasuredValue {
  + timestamp : datetime
  + value : float
}

enum Unit {
  CELSIUS
  WATT
}

class EMonitor {
  + checkThresholds() : void
  + sendAlert(email : string) : void
}

SensorController "1" *-- "1..*" Inhabitant
SensorController "1" *-- "1" Apartment
Apartment "1" *-- "2..*" Room
Room "1" *-- "1..*" Sensor
Sensor "1" *-- "1..*" MeasuredValue
Sensor "1" *-- "1" MeasuredValue : lastValue
Inhabitant "1" --> "1..*" Sensor : configures
Inhabitant "1" --> "1..*" Sensor : queries
EMonitor "1" --> "1" SensorController : checks
EMonitor "1" --> "1" Apartment : sendsAlertTo

TemperatureSensor --|> Sensor
PowerSensor --|> Sensor

@enduml

